create policy "Owners upload kindle outbox" on storage.objects for insert to authenticated with check (bucket_id = 'kindle-outbox' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "Owners read kindle outbox" on storage.objects for select to authenticated using (bucket_id = 'kindle-outbox' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "Owners delete kindle outbox" on storage.objects for delete to authenticated using (bucket_id = 'kindle-outbox' and (storage.foldername(name))[1] = auth.uid()::text);